func (c *HTTPClient) load(key string, ttl time.Duration) (string, time.Duration, error) {
	req, err := c.deserializeReq(key)
	if err != nil {
		return "", 0, err
	}
	resp, err := c.hc.Do(req)
	if err != nil {
		return "", 0, err
	}
	defer resp.Body.Close()
	value := c.serializeResponse(resp)
	log.Trace("New request cached", "req", key, "resp", value)
	return value, ttl, nil
}

